BEGIN;
SET LOCAL statement_timeout='30s';
SET LOCAL app.database_plane='neon';
SELECT pg_advisory_xact_lock(hashtext('bp-target-catalog-v1'));
CREATE TEMP TABLE expected AS SELECT value->>'code' code,value->>'existing' existing,value->>'proposal' proposal,value->'scopes' scopes FROM jsonb_array_elements('[{"code":"neon.relationship.bp_target.enter","existing":"neon.relationship.business_partner.enter","proposal":"0554688dd63b108c396d6720c826d972dee5f37a095fc6d090eb6fc1ef82ce59","scopes":["tenant"]},{"code":"neon.relationship.bp_target.discover","existing":"neon.relationship.business_partner.read","proposal":"02e3f444102cc1e5d2e40b0f0ad8c3f6d0bfa79223cb0398972d8499b5c5d817","scopes":["tenant"]},{"code":"neon.relationship.bp_target.read","existing":"neon.relationship.business_partner.read","proposal":"cba0249d009c920aa09e9154e739fe7266e29041ab035efbf6890fd02cb3f995","scopes":["tenant"]},{"code":"neon.relationship.bp_target.navigate_manage","existing":"neon.relationship.business_partner.read","proposal":"6d9b6decc34e78e644ca7fdcf65cc1c94ba95efb5788c2d74d9cb936fd141e22","scopes":["tenant"]},{"code":"neon.relationship.bp_target.navigate_overview","existing":"neon.relationship.business_partner.read","proposal":"7bba276033e64e1646dabeb11fc87e8321615565f06234dcabf5e400b05a7fe4","scopes":["tenant"]},{"code":"neon.relationship.bp_target.export","existing":"neon.relationship.business_partner.read","proposal":"9326147021ff807e0431c08bc5617e407e70cd3bb7e1b4ba87dc68d5d320020d","scopes":["tenant"]},{"code":"neon.relationship.bp_target.configure_company","existing":"neon.relationship.entity_case.create","proposal":"5a436208c25378a6d960056e27041ae0aac3cdb03125b05ffad4fb3d2b06ef11","scopes":["operating_organization","company_code"]},{"code":"neon.relationship.bp_target.import","existing":"neon.relationship.business_partner.read","proposal":"b886afa832c9baa8bd818619fa8dc3306381ad97d8f93909595553a793df84e4","scopes":["tenant"]},{"code":"neon.relationship.bp_target.identity_read","existing":"neon.relationship.business_partner_identity.read","proposal":"d0e0f2cd5dc2da39ccc447b6838be29eb4d14a4984771a2d4767333bb9840dbe","scopes":["tenant"]},{"code":"neon.relationship.bp_target.contacts_read","existing":"neon.relationship.business_partner_contact.read","proposal":"0aab88da4526fb2749faa489cd6bf41068da4dc858164c6f1b369420b94e3eb9","scopes":["tenant"]},{"code":"neon.relationship.bp_target.addresses_read","existing":"neon.relationship.business_partner_address.read","proposal":"28ec4ced6a19a46bd80851b1df5ac6e58e2b71f5293bbc47d514428a390db7f4","scopes":["tenant"]},{"code":"neon.relationship.bp_target.identifier_read","existing":"neon.relationship.business_partner_identifier.read_masked","proposal":"b5647f5f65cb1bebe01f08485cacef349fc17df97098b489807664ed5c5b6727","scopes":["tenant"]},{"code":"neon.relationship.bp_target.tax_read","existing":"neon.relationship.business_partner_tax.read_masked","proposal":"5da8784e84b314eb3fc5991661c4736d46e7ab650e74440ad884f609fe9b042c","scopes":["tenant"]},{"code":"neon.relationship.bp_target.bank_read","existing":"neon.relationship.business_partner_bank.read_masked","proposal":"26e120dd4d98dfcc8c3ffa83e672d58bdcf70d3beebeb8e4ac2f53b8d0564b8e","scopes":["tenant"]},{"code":"neon.relationship.bp_target.qualification_read","existing":"neon.relationship.business_partner_qualification.read","proposal":"5c1a6665ec4a4654e114370acd51225906480e2249903aec8aa90f42d8ea3850","scopes":["tenant"]},{"code":"neon.relationship.bp_target.certificate_read","existing":"neon.relationship.business_partner_certificate.read","proposal":"0d6fc71b68894b721550d1a5c11c9b18fca971227e0086fa66f0de812ed2bbab","scopes":["tenant"]},{"code":"neon.relationship.bp_target.credit_read","existing":"neon.relationship.business_partner_credit.read","proposal":"7f0f507c539eaeaccfe01442984038f5d2464f88ca89c43eeee0eb327ca42102","scopes":["operating_organization","company_code"]},{"code":"neon.relationship.bp_target.requests_read","existing":"neon.relationship.entity_case.read","proposal":"bf497271c96e5f1a5a75cc8ea9fc4f4d0a3d64a2fafaa39e62c28f32af88b447","scopes":["tenant"]},{"code":"neon.relationship.bp_target.activity_read","existing":"neon.relationship.business_partner_activity.read","proposal":"bd35273f50ed334ec6846ce2b14310efa99ee976c8490c54e6f9c3d894cc4a0f","scopes":["tenant"]},{"code":"neon.relationship.bp_target.network_read","existing":"neon.relationship.business_partner_network.read","proposal":"a0da4bc917f6f4356f96072b7af2f61f0d4a17894d9c38b00510a0a1c434beb9","scopes":["operating_organization","company_code"]},{"code":"neon.relationship.bp_target.comments_read","existing":"collaboration.comment.read","proposal":"26f6d48328b44e4d85a749ddb2d53d2716dca8ec8d8d7b25ecef369467016779","scopes":["tenant"]},{"code":"neon.relationship.bp_target.attachments_read","existing":"document.attachment.read","proposal":"ecba0c99947eded022acfbeb44347f2a5d34f18e5b579afa8995482467ab12c8","scopes":["tenant"]},{"code":"neon.relationship.bp_target.bank_reveal","existing":"neon.relationship.business_partner_bank.reveal","proposal":"f7094891f34c925059442cfe99461254903c81b2ae17c277c83426ae38ce029b","scopes":["tenant"]},{"code":"neon.relationship.bp_target.tax_reveal","existing":"neon.relationship.business_partner_tax.reveal","proposal":"dee47f7e22852e214a94328ebdfbb4ab37a845d209b92f98a4e5ddeb7f67ba51","scopes":["tenant"]},{"code":"neon.relationship.bp_target.qualification_company","existing":"neon.supplier.qualification.admin","proposal":"aa36e7adc9ffe1a90ca6eef01acece0ae37d3f31c014545645dbb5f0a4e140b1","scopes":["operating_organization","company_code"]},{"code":"neon.relationship.bp_target.supplier_company_read","existing":"neon.relationship.business_partner.read","proposal":"d4ab48088849a22dd1d3dca78ec8bb2d0ff2fc452c139e0c821886119199010d","scopes":["operating_organization","company_code"]},{"code":"neon.relationship.bp_target.customer_company_read","existing":"neon.relationship.business_partner.read","proposal":"95e2ce2b79a244821b21ae7cae331e2acede9dd317ad0b3bb1293b245cdd4c22","scopes":["operating_organization","company_code"]}]'::jsonb);
CREATE TEMP TABLE protected_before (name text PRIMARY KEY, fingerprint text);
DO $guard$ DECLARE t record; fingerprint text; BEGIN
 IF current_database()<>'athyper_neon' OR NOT EXISTS(SELECT 1 FROM control.module WHERE code='fnd' AND status='active') THEN RAISE EXCEPTION 'Wrong catalog plane/module'; END IF;
 IF NOT EXISTS(SELECT 1 FROM runtime_meta.release_activation_head WHERE publication_key='metadata.entity.business_partner.local-master-data.cirrusatlantic' AND row_version=17 AND applied_release_id='01a08532-31a1-7493-8953-ca4528dda3de'::uuid) THEN RAISE EXCEPTION 'Activation head changed'; END IF;
 FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='authz' AND tablename NOT IN ('permission','permission_scope_kind') ORDER BY tablename LOOP
 EXECUTE format('LOCK TABLE authz.%I IN SHARE MODE',t.tablename);
 EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(r)::text,chr(10) ORDER BY to_jsonb(r)::text),'''')) FROM authz.%I r',t.tablename) INTO fingerprint;
 INSERT INTO protected_before VALUES(t.tablename,fingerprint);
 END LOOP;
END $guard$;
CREATE TEMP TABLE definitions AS SELECT e.*,coalesce(p.module_id,m.id) module_id,coalesce(p.risk_tier,'low') risk_tier,coalesce(p.requires_mfa,false) requires_mfa,coalesce(p.requires_sod,false) requires_sod
FROM expected e JOIN control.module m ON m.code='fnd' AND m.status='active' LEFT JOIN authz.permission p ON p.canonical_code=e.existing;
INSERT INTO authz.permission(canonical_code,permission_kind,module_id,risk_tier,requires_mfa,requires_sod,is_shareable,is_delegable,is_overridable,metadata,status,created_by)
SELECT code,'entity_operation',module_id,risk_tier,requires_mfa,requires_sod,false,false,false,
jsonb_build_object('_seed',jsonb_build_object('pack','neon.bp-target-permissions','version','1.0.0'),'proposalSha256',proposal,'packetRevision','23a4203d695989429bd7b1c3adbeca108400d742683c050dda35b061f8538382'),'published','00000000-0000-0000-0000-000000000000'::uuid FROM definitions ON CONFLICT(canonical_code) DO NOTHING;
INSERT INTO authz.permission_scope_kind(permission_id,scope_kind,propagation_mode,status,created_by)
SELECT p.id,s.value,'exact','active','00000000-0000-0000-0000-000000000000'::uuid FROM definitions d JOIN authz.permission p ON p.canonical_code=d.code CROSS JOIN LATERAL jsonb_array_elements_text(d.scopes) s(value)
ON CONFLICT(permission_id,scope_kind,propagation_mode) DO NOTHING;
SET CONSTRAINTS ALL IMMEDIATE;
DO $verify$ DECLARE t record; fingerprint text; BEGIN
 IF EXISTS(SELECT 1 FROM definitions d JOIN authz.permission p ON p.canonical_code=d.code WHERE p.status<>'published' OR p.permission_kind<>'entity_operation' OR p.module_id<>d.module_id OR p.risk_tier<>d.risk_tier OR p.requires_mfa<>d.requires_mfa OR p.requires_sod<>d.requires_sod OR p.is_shareable OR p.is_delegable OR p.is_overridable OR p.metadata->>'proposalSha256' IS DISTINCT FROM d.proposal OR (SELECT jsonb_agg(s.scope_kind ORDER BY s.scope_kind) FROM authz.permission_scope_kind s WHERE s.permission_id=p.id AND s.status='active' AND s.propagation_mode='exact') IS DISTINCT FROM (SELECT jsonb_agg(v ORDER BY v) FROM jsonb_array_elements_text(d.scopes) v) OR EXISTS(SELECT 1 FROM authz.permission_scope_kind s WHERE s.permission_id=p.id AND (s.propagation_mode<>'exact' OR s.status<>'active'))) THEN RAISE EXCEPTION 'Existing catalog definition conflicts; no overwrite permitted'; END IF;
 FOR t IN SELECT * FROM protected_before LOOP
 EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(r)::text,chr(10) ORDER BY to_jsonb(r)::text),'''')) FROM authz.%I r',t.name) INTO fingerprint;
 IF fingerprint IS DISTINCT FROM t.fingerprint THEN RAISE EXCEPTION 'Protected authorization table changed: %',t.name; END IF;
 END LOOP;
END $verify$;
SELECT jsonb_build_object('schemaVersion',1,'kind','bp_target_catalog_installation','applied',true,'packetRevision','23a4203d695989429bd7b1c3adbeca108400d742683c050dda35b061f8538382','selectionSha256','9d9c1a6ec6dede37e108f7a2cd73daea91e34d5364963cea7c36a07058924861','capturedAt',clock_timestamp(),'protectedAuthorizationTables',(SELECT count(*) FROM protected_before),'grantsUnchanged',true,'activationChanged',false,'permissions',(SELECT jsonb_agg(jsonb_build_object('id',p.id,'code',p.canonical_code,'status',p.status,'requiresMfa',p.requires_mfa,'requiresSod',p.requires_sod) ORDER BY p.canonical_code) FROM authz.permission p JOIN expected e ON e.code=p.canonical_code));
COMMIT;
